body.script:
const vocab = [
    { tr: "Merhaba", de: "Hallo" },
    { tr: "Teşekkür ederim", de: "Danke" },
    { tr: "Evet", de: "Ja" },
    { tr: "Hayır", de: "Nein" },
    { tr: "Lütfen", de: "Bitte" },
    { tr: "Nasılsın?", de: "Wie geht es dir?" },
    { tr: "İyiyim", de: "Mir geht es gut" },
    { tr: "Güle güle", de: "Tschüss (sagt der Bleibende)" },
    { tr: "Hoşça kal", de: "Tschüss (sagt der Gehende)" },
    { tr: "Günaydın", de: "Guten Morgen" }
];

let currentIndex = 0;

function toggleTranslation() {
    const trans = document.getElementById("germanWord");
    trans.style.display = trans.style.display === "block" ? "none" : "block";
}

function nextWord() {
    currentIndex = (currentIndex + 1) % vocab.length;
    document.getElementById("turkishWord").innerText = vocab[currentIndex].tr;
    document.getElementById("germanWord").innerText = vocab[currentIndex].de;
    document.getElementById("germanWord").style.display = "none";
}
